#include <bits/stdc++.h>
using namespace std;

#define nl "\n"
#define all(x) (x).begin(), (x).end()

typedef long long ll;
typedef vector<ll> vll;

void solve(){
    ll n; cin>>n;
    vll a(3*n), p(3* n+1);
    for(auto& x:a) cin>>x;
    sort(all(a), greater<ll>());
    for(ll i=0;i<3*n; i++) p[i+1] = p[i] + a[i];
    
    auto val = [&](ll x, ll y) -> ll {
        return 2* p[x] + p[x+2*y] + 3*p[3*n-2*x-y];
    };
    
    ll ans = 0;
    for(ll x =0; x<=n; x++){
        ll limit = n-x;
        ll step = max(1LL, (ll)sqrt(limit));
        ll best = 0, bestVal = val(x,0);
        for(ll y = step; y<= limit; y+=step){
            ll cur = val(x,y);
            if(cur > bestVal){
                best = y;
                bestVal = cur;
            }
        }
        if(val(x, limit) > bestVal) best = limit;
        
        ll l = max(0LL, best - step);
        ll r = min(limit, best + step);
        for(ll y = l; y<= r; y++){
            ans = max(ans, val(x, y));
        }
    }
    
    cout<<ans<<nl;
    
}

int main() {
	// your code goes here
	ll t =1;
	cin>>t;
	while(t--){
	    solve();
	}
	return 0;

}
